#include <bits/stdc++.h>
using namespace std;

#define int long long

const int N = 65, M = 1e9 + 7, L = 18;

int n, m, p, a[N], C[N][N], f[N][1 << L], b[N];
int cnt[1 << L], fac[N], vis[N];

signed main() {
	scanf("%lld", &n);

	fac[0] = 1;
	for (int i = 1; i <= n; i++)
		fac[i] = fac[i - 1] * i % M;

	for (int i = 0; i <= n; i++) {
		C[i][0] = 1;
		for (int j = 1; j <= i; j++)
			C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % M;
	}

	for (int i = 1; i <= n; i++)
		scanf("%lld", &a[i]);

	sort(a + 1, a + n + 1);

	for (int i = 1; i <= n; i++) {
		if (!vis[i]) {
			int flag = 0;
			vis[i] = m;

			for (int j = i + 1; j <= n; j++) {
				if (a[j] % a[i] == 0) {
					vis[j] = -1;
					b[j] |= 1LL << vis[i];
					flag = 1;
				}
			}

			if (flag)
				m++;
			else {
				vis[i] = -2;
				p++;
			}
		}
	}

	for (int i = 1; i <= n; i++)
		if (vis[i] == -1)
			cnt[b[i]]++;

	for (int i = (1LL << m) - 1; i >= 0; i--)
		for (int j = i; j; j = (j - 1) & i)
			cnt[i] += cnt[i ^ j];

	f[0][0] = 1;

	for (int i = 1; i <= n; i++)
		if (vis[i] == -1)
			for (int j = i - 1; j >= 0; j--)
				for (int k = 0; k < (1LL << m); k++)
					(f[j + 1][k | b[i]] += f[j][k]) %= M;

	for (int i = 0; i <= n - m - p; i++) {
		for (int j = 0; j < (1LL << m); j++)
			if (f[i][j])
				f[i][j] = f[i][j] * fac[cnt[j] - i] % M
				          * C[n - m - p - i][cnt[j] - i] % M;

		for (int j = 0; j < (1LL << m); j++) {
			for (int k = 1; k <= n; k++) {
				if (vis[k] == -1 && (b[k] & j) != 0 && (b[k] | j) != j) {
					int next = j | b[k];
					int diff = cnt[next] - cnt[j] - 1;
					(f[i][next] += f[i][j]
						* C[n - m - p - cnt[j] - 1][diff] % M
						* fac[diff] % M) %= M;
				}
			}
		}

		if (f[i][(1LL << m) - 1]) {
			printf("%lld\n", f[i][(1LL << m) - 1]);
			return 0;
		}
	}

	return 0;
}

